export default async (_ctx, client) => {
  const { entities, metadata } = await client.entities.list({ entity_type: 'social-signal', limit: 200 });
  let ok = 0; const errs = [];
  for (const e of entities) {
    try { await client.entities.delete({ entity_id: e.id }); ok++; }
    catch (err) { errs.push(`${e.id}: ${String(err).slice(0, 120)}`); }
  }
  return { total_before: metadata.total_count, page: entities.length, deleted: ok, errors: errs.slice(0, 5), error_count: errs.length };
};

export default async (_ctx, client) => {
  const { entities, metadata } = await client.entities.list({ entity_type: 'social-signal', limit: 190 });
  let ok = 0; const errs = [];
  for (const e of entities) {
    try { await client.entities.delete({ entity_id: e.id }); ok++; }
    catch (err) { errs.push(`${e.id}: ${String(err).slice(0, 100)}`); }
  }
  return { remaining_before: metadata.total_count, deleted: ok, error_count: errs.length, errors: errs.slice(0, 3) };
};

export default async (_ctx, client) => {
  const before = await client.entities.list({ entity_type: 'social-signal', limit: 1 });
  let typeDeleted = null;
  try { typeDeleted = await client.entitySchema.deleteType({ slug: 'social-signal' }); }
  catch (err) { typeDeleted = `ERROR: ${String(err).slice(0, 200)}`; }
  const types = await client.entitySchema.listTypes();
  const still = (types.entity_types ?? types).some?.((t) => t.slug === 'social-signal');
  return { entities_remaining: before.metadata.total_count, typeDeleted, type_still_listed: still };
};

