/**
 * Deterministic delivery for the Social Interest Radar Behavior.
 *
 * The model ranks posts and writes a ready-to-send draft reply for each. This
 * reaction owns every durable side effect: one reply event per source post
 * carrying the draft plus a click-to-compose link, followed by one digest
 * notification. Both writes carry durable idempotency keys because the reaction
 * executor retries a failed script.
 *
 * Platform asymmetry is deliberate and load-bearing:
 *   • X  — events carry a real permalink and the origin_id IS the tweet id, so
 *     we build an intent URL that opens X's composer with the draft prefilled.
 *   • LinkedIn — the home-feed scrape keys off `componentkey`, which is not an
 *     activity id, so no /feed/update permalink exists. We emit the draft with
 *     no compose link rather than a fake one. Fix the ingest, not this file.
 */
import type {
  KnowledgeSaveResult,
  ReactionClient,
  ReactionContext,
} from "@lobu/connector-sdk";

export const input = {
  type: "object",
  properties: {
    digest_title: { type: "string", minLength: 1, maxLength: 200 },
    analysis_summary: { type: "string" },
    items: {
      type: "array",
      maxItems: 8,
      items: {
        type: "object",
        properties: {
          platform: { enum: ["x", "linkedin"] },
          author: { type: "string", minLength: 1 },
          snippet: { type: "string" },
          why: { type: "string", minLength: 1 },
          draft: { type: "string", minLength: 1, maxLength: 1200 },
          priority: { enum: ["high", "normal", "low"] },
          source_origin_id: { type: "string", minLength: 1 },
          source_event_id: { type: "integer", minimum: 1 },
          source_url: { type: "string" },
        },
        required: [
          "platform",
          "author",
          "snippet",
          "why",
          "draft",
          "priority",
          "source_origin_id",
          "source_event_id",
        ],
      },
    },
  },
  required: ["digest_title", "analysis_summary", "items"],
};

interface RadarItem {
  platform: "x" | "linkedin";
  author: string;
  snippet: string;
  why: string;
  draft: string;
  priority: "high" | "normal" | "low";
  source_origin_id: string;
  source_event_id: number;
  source_url?: string;
}

interface RadarOutput {
  digest_title: string;
  analysis_summary: string;
  items: RadarItem[];
}

function producerRunKey(ctx: ReactionContext): string {
  return ctx.window.run_id != null
    ? `run:${ctx.window.run_id}`
