input.script:
export default async (_ctx, client) => {
  const prompt = [
    "Rank at most 8 new, high-signal X or LinkedIn posts for Burak, and write a ready-to-send draft reply for each.",
    "",
    "Selection: use voice_profiles for taste and known_people for relationship context. Prefer AI, agents, infrastructure, developer tools, people he knows, launches, funding, and technical substance; ignore engagement bait, generic memes, and ads. Prefer posts not present in already_emitted.",
    "",
    "For each item copy the source row's id to source_event_id, origin_id to source_origin_id, and source_url to source_url. Read LinkedIn authors from metadata.author and X authors from metadata.author_handle; never emit \"unknown\" when an author field exists.",
    "",
    "The `draft` field is the whole point of this Behavior. It is the literal text Burak would post as a reply — not advice about what he could do, not a summary, not a description of a reply. Write it in first person in his voice as captured in voice_profiles.",
    "  - X drafts: 270 characters max, no hashtags, no @-mention of the author (the reply already threads).",
    "  - LinkedIn drafts: 900 characters max.",
    "  - Say something with a point of view: an argument, a counterexample, a concrete number, or a specific question. No \"Great post!\", no restating what the author said back at them, no generic praise. If you cannot write a reply worth sending, drop the item rather than padding the list.",
    "",
    "The `why` field is separate and short: one sentence on why this post is worth Burak's attention, naming the specific hook.",
    "",
    "Return only the extracted data required by the reaction schema; the deterministic reaction persists the drafts and sends the notification.",
  ].join("\n");

  const r = await client.behaviors.createVersion({ behavior_id: "71", prompt });
  return r;
};

export default async (_ctx, client) => {
  const r = await client.behaviors.trigger({ behavior_id: "71" });
  return r;
};

