export default async (ctx, client) => {
  const rows = await client.query("SELECT metadata->>'compose_url' AS u, metadata->>'draft' AS d FROM events WHERE id = 4754278");
  const url = rows[0].u;
  const draft = rows[0].d;

  const nav = await client.operations.execute({
    connection_id: 432, operation_key: 'navigate',
    input: { url, open_in_new_tab: true, wait_for_load: true },
  });
  if (nav.status !== 'completed') {
    return { step: 'navigate', status: nav.status, error: nav.error_message, output: nav.output };
  }
  await ctx.sleep(6000);

  const evalRes = await client.operations.execute({
    connection_id: 432, operation_key: 'evaluate',
    input: {
      tab_id: nav.output.tab_id,
      await_promise: true,
      expression: `(async () => {
        const out = { href: location.href, title: document.title };
        const box = document.querySelector('[data-testid="tweetTextarea_0"]');
        out.composer_found = !!box;
        out.composer_text = box ? box.innerText : null;
        const body = document.body ? document.body.innerText : '';
        out.replying_to = (body.match(/Replying to[\\s\\S]{0,40}/) || [null])[0];
        out.login_wall = /Sign in to X|Log in to X|Create your account/i.test(body);
        return out;
      })()`,
    },
  });
  return { draft, url, nav_status: nav.status, tab_id: nav.output.tab_id, evaluate: evalRes };
};

