export default async (ctx, client) => {
  const rows = await client.query("SELECT metadata->>'draft' AS d FROM events WHERE id = 4754278");
  const draft = rows[0].d;
  const id = '2083959735481716957';
  const t = encodeURIComponent(draft);
  const variants = {
    intent_tweet: `https://x.com/intent/tweet?in_reply_to=${id}&text=${t}`,
    compose_post: `https://x.com/compose/post?in_reply_to=${id}&text=${t}`,
  };
  const results = {};
  for (const [name, url] of Object.entries(variants)) {
    const nav = await client.operations.execute({
      connection_id: 432, operation_key: 'navigate',
      input: { url, open_in_new_tab: true, wait_for_load: true },
    });
    if (nav.status !== 'completed') { results[name] = { nav: nav.status, err: nav.error_message }; continue; }
    await ctx.sleep(9000);
    const r = await client.operations.execute({
      connection_id: 432, operation_key: 'evaluate',
      input: { tab_id: nav.output.tab_id, await_promise: true,
        expression: `(async () => {
          const box = document.querySelector('[data-testid="tweetTextarea_0"]');
          const body = document.body ? document.body.innerText : '';
          return {
            href: location.href,
            composer_text: box ? box.innerText.trim() : null,
            replying_to: (body.match(/Replying to @[A-Za-z0-9_]+/) || [null])[0],
          };
        })()` },
    });
    results[name] = { tab_id: nav.output.tab_id, ...(r.output ? r.output.value : { raw: r }) };
  }
  return { draft_head: draft.slice(0, 60), results };
};

