result.output:
"/**
 * Deterministic delivery for the Social Interest Radar Behavior.
 *
 * The model ranks posts and writes a ready-to-send draft reply for each. This
 * reaction owns every durable side effect: one reply event per source post
 * carrying the draft plus a permalink to the post, followed by one digest
 * notification. Both writes carry durable idempotency keys because the reaction
 * executor retries a failed script.
 *
 * Neither platform can be handed a prefilled composer from a URL:
 *   • X ignores `?text=` outright. Verified 2026-08-02 against the real signed-in
 *     x.com through the paired Chrome: /intent/post, /intent/tweet (which just
 *     redirects to /intent/post) and /compose/post all render an EMPTY composer,
 *     with and without `in_reply_to`. `in_reply_to` itself works — the reply
 *     target resolves — so only the text is dropped. Do not re-add an intent URL.
 *   • LinkedIn has the staging action (`prepare_comment`) but its home-feed
 *     scrape keys off `componentkey`, not an activity id, so there is no
 *     /feed/update permalink to aim it at. Fix the ingest, not this file.
 *
 * So the link here is a plain permalink to the source post and the draft is text
 * to be staged by a connector action. Verified working through the chrome
 * connector: navigate → get_accessibility_tree → click_ref → type_ref puts the
 * draft in X's reply box exactly (252/252 chars, em dash and apostrophes intact)
 * without submitting. That sequence belongs in an `x.prepare_reply` action
 * mirroring `linkedin.prepare_comment`, NOT inlined into this reaction.
 */
import type {
  KnowledgeSaveResult,
  ReactionClient,
  ReactionContext,
} from "@lobu/connector-sdk";

export const input = {
  type: "object",
  properties: {
    digest_title: { type: "string", minLength: 1, maxLength: 200 },
    analysis_summary: { type: "string" },
    items: {
      type: "array",
      maxItems: 8,
      items: {
        type: "object",
        properties: {
          platform: { enum: ["x", "linkedin"] },
          author: { type: "string", minLength: 1 },
          snippet: { type: "string" },
          why: { type: "string", minLength: 1 },
          draft: { type: "string", minLength: 1, maxLength: 1200 },
          priority: { enum: ["high", "normal", "low"] },
          source_origin_id: { type: "string", minLength: 1 },
          source_event_id: { type: "integer", minimum: 1 },
          source_url: { type: "string" },
        },
        required: [
          "platform",
          "author",
          "snippet",
          "why",
          "draft",
          "priority",
          "source_origin_id",
          "source_event_id",
        ],
      },
    },
  },
  required: ["digest_title", "analysis_summary", "items"],
};

interface RadarItem {
  platform: "x" | "linkedin";
  author: string;
  snippet: string;
  why: string;
  draft: string;
  priority: "high" | "normal" | "low";
  source_origin_id: string;
  source_event_id: number;
  source_url?: string;
}

interface RadarOutput {
  digest_title: string;
  analysis_summary: string;
  items: RadarItem[];
}

function producerRunKey(ctx: ReactionContext): string {
  return ctx.window.run_id != null
    ? `run:${ctx.window.run_id}`
    : `window:${ctx.window.id}:version:${ctx.behavior.version}`;
}

function belongsToProducer(
  result: KnowledgeSaveResult,
  producerKey: string
): boolean {
  return result.created || result.metadata.producer_run_key === producerKey;
}

/**
 * Permalink to the post being replied to, or null when the platform cannot
 * address it. X home-timeline events store the numeric tweet id as origin_id and
 * also carry a real source_url. LinkedIn's source_url is the bare /feed/ for
 * every row, which is useless as a target — see the file header.
 */
function postUrl(item: RadarItem): string | null {
  if (item.platform !== "x") return null;
  if (item.source_url?.startsWith("https://x.com/")) return item.source_url;
  if (!/^\d{6,}$/.test(item.source_origin_id)) return null;
  return `https://x.com/i/web/status/${item.source_origin_id}`;
}

function itemContent(item: RadarItem, post: string | null): string {
  const lines = [item.draft, "", `Why: ${item.why}`];
  if (post) lines.push("", `[Open post to reply](${post})`);
  return lines.join("\n");
}

function notificationBody(lines: string[]): string {
  const body = lines.join("\n");
  return body.length <= 1000 ? body : `${body.slice(0, 997)}...`;
}

export default async (
  ctx: ReactionContext,
  client: ReactionClient
): Promise<void> => {
  const output = ctx.extracted_data as unknown as RadarOutput;
  if (output.items.length === 0) return;

  const producerKey = producerRunKey(ctx);
  const delivered: Array<{ item: RadarItem; replyId: number }> = [];

  for (const item of output.items) {
    const post = postUrl(item);
    const reply = await client.knowledge.save({
      content: itemContent(item, post),
      title: `Draft reply to ${item.author} on ${item.platform}`,
      author: "personal-agent",
      semantic_type: "social_signal",
      payload_type: "markdown",
      parent_event_id: item.source_event_id,
      idempotency_key: `social-radar:source:${item.source_origin_id}`,
      metadata: {
        ...item,
        post_url: post,
        producer_run_key: producerKey,
        behavior_id: ctx.behavior.id,
        window_id: ctx.window.id,
      },
      behavior_source: {
        behavior_id: ctx.behavior.id,
        window_id: ctx.window.id,
      },
    });

    // A later Behavior run may rank the same post again. knowledge.save returns
    // its original event, but only the run that first created it should notify.
    // A retry of THAT run still qualifies through the stored producer key.
    if (belongsToProducer(reply, producerKey)) {
      delivered.push({ item, replyId: reply.id });
    }
  }

  if (delivered.length === 0) return;

  const contentIds = delivered.flatMap(({ item, replyId }) => [
    item.source_event_id,
    replyId,
  ]);
  const resourceUrl = `/${encodeURIComponent(ctx.organization_slug)}/memory?content_ids=${contentIds.join(",")}`;
  const body = notificationBody(
    delivered.map(
      ({ item }) => `[${item.priority}] ${item.author} (${item.platform}) — ${item.draft}`
    )
  );

  await client.notifications.send({
    title: output.digest_title,
    body,
    recipients: "admins",
    resource_url: resourceUrl,
    idempotency_key: `social-radar:notification:${producerKey}`,
    behavior_source: {
      behavior_id: ctx.behavior.id,
      window_id: ctx.window.id,
    },
  });
};
"

