							{
								ref_id: 36,
								role: "textbox",
								name: overrides.composerName ?? "Post text",
							},
						],
					};
				case "type_ref":
					typedText = input.text as string;
					return { ok: true };
				case "evaluate":
					return {
						value: {
							staged_text: overrides.stagedText ?? typedText,
							composer_present: true,
							submit_enabled: true,
						},
					};
				default:
					return { ok: true };
			}
		},
	};
