export default async (ctx, client) => {
  const CONN = 369; // Mac mini chrome — same device worker as the x connection (399)
  const url = 'https://x.com/martin_casado/status/2084003533943398863';
  const draft = "Demos are stunning but the gap between vibe-coded output and something maintainable is still enormous. The real test isn't what AI produces, it's what survives when the person who prompted it walks away and someone else has to debug it.";

  const steps = {};
  const nav = await client.operations.execute({
    connection_id: CONN, operation_key: 'navigate',
    input: { url, open_in_new_tab: true, wait_for_load: true },
  });
  steps.navigate = nav.status;
  const tab = nav.output.tab_id;

  await client.operations.execute({
    connection_id: CONN, operation_key: 'wait_for_selector',
    input: { tab_id: tab, selector: '[data-testid="tweetTextarea_0"]', timeout_ms: 15000 },
  }).then((r) => { steps.wait_for_selector = r.status; }).catch((e) => { steps.wait_for_selector = String(e).slice(0, 120); });

  const tree = await client.operations.execute({
    connection_id: CONN, operation_key: 'get_accessibility_tree',
    input: { tab_id: tab, filter: 'interactive' },
  });
  const nodes = (tree.output && tree.output.tree) || [];
  const boxes = nodes.filter((n) => n.role === 'textbox');
  const box = boxes.find((n) => /post text/i.test(n.name || '')) ?? boxes[0];
  steps.composer_found = box ? { ref_id: box.ref_id, name: box.name } : null;
  if (!box) return { steps, tab, note: 'no textbox' };
  const ref = { ref_id: box.ref_id, document_epoch: tree.output.document_epoch };

  steps.click = (await client.operations.execute({
    connection_id: CONN, operation_key: 'click_ref', input: { tab_id: tab, ref },
  })).status;
  await ctx.sleep(1500);
  steps.type = (await client.operations.execute({
    connection_id: CONN, operation_key: 'type_ref', input: { tab_id: tab, ref, text: draft, clear_first: true },
  })).status;
  await ctx.sleep(3000);

  const read = await client.operations.execute({
    connection_id: CONN, operation_key: 'evaluate',
    input: { tab_id: tab, await_promise: true,
      expression: `(async () => {
        const b = document.querySelector('[data-testid="tweetTextarea_0"]');
        const btn = document.querySelector('[data-testid="tweetButtonInline"]') || document.querySelector('[data-testid="tweetButton"]');
        const body = document.body ? document.body.innerText : '';
        return {
          staged_text: b ? b.innerText.replace(/\\n+$/, '') : null,
          submit_enabled: btn ? btn.getAttribute('aria-disabled') !== 'true' : null,
          replying_to: (body.match(/Replying to @[A-Za-z0-9_]+/) || [null])[0],
        };
      })()` },
  });
  const v = read.output ? read.output.value : read;
  return {
    steps, tab,
    draft_len: draft.length,
    staged_len: v.staged_text ? v.staged_text.length : 0,
    exact_match: v.staged_text === draft,
    submit_enabled: v.submit_enabled,
    replying_to: v.replying_to,
  };
};

