// human was pointed at it and is expected to read and send it. Leaving it
// owned meant the reaper force-closed the draft after EXTENSION_TAB_TTL_MS.
async function tool_release_tab(chromeApi, args, runCtx) {
	const tabId = args?.tab_id;
	if (typeof tabId !== "number") {
		throw new Error("release_tab: 'tab_id' is required");
	}
	const holderRunId = runCtx?.holderRunId ?? null;
	if (!(await isOwnedTabForRun(tabId, holderRunId))) {
		throw new Error(
			`release_tab: tab ${tabId} is not owned by this connector run — only a tab the extension created for this run can be handed to the user.`,
		);
	}
	await forgetOwnedTab(tabId);
	return { ok: true, observation: { tab_id: tabId, released: true } };
}

