// get_accessibility_tree({ tab_id?, filter? })
async function tool_get_accessibility_tree(chromeApi, args, runCtx) {
	const tabId = args?.tab_id ?? runCtx.scratchTabId;
	if (tabId == null) throw new Error("get_accessibility_tree: no tab");
	// The connector author's allowedOrigins gate applies to the current URL.
	await enforceAllowedOriginFromTab(chromeApi, tabId, runCtx);
	const filter = args?.filter ?? "interactive";
	if (!["interactive", "visible", "all"].includes(filter)) {
		throw new Error(`get_accessibility_tree: bad filter '${filter}'`);
	}

	// Inject the bundled walker into an isolated world, then call __lobuExtract.
	return withDebugger(chromeApi, tabId, async () => {
		const ctxId = await injectAccessibilityScript(chromeApi, tabId);
		const extracted = await evalInContext(
			chromeApi,
			tabId,
			ctxId,
			`JSON.stringify(__lobuExtract({ filter: ${JSON.stringify(filter)} }))`,
		);
		const parsed =
			typeof extracted === "string" ? JSON.parse(extracted) : extracted;
		return {
			ok: true,
			observation: {
				tab_id: tabId,
				document_epoch: parsed.document_epoch,
				current_url: parsed.current_url,
				title: parsed.title,
				tree: parsed.tree,
			},
		};
	});
}

// click_ref({ ref, tab_id?, button?, click_count? })
async function tool_click_ref(chromeApi, args, runCtx) {
	const ref = args?.ref;
	if (!ref || typeof ref !== "object")
		throw new Error("click_ref: 'ref' is required");
	const { ref_id, document_epoch } = ref;
	const tabId = args?.tab_id ?? runCtx.scratchTabId;
	if (tabId == null) throw new Error("click_ref: no tab");
	await enforceAllowedOriginFromTab(chromeApi, tabId, runCtx);
	const button = args.button ?? "left";
	const clickCount = args.click_count ?? 1;

	return withDebugger(chromeApi, tabId, async () => {
		const ctxId = await injectAccessibilityScript(chromeApi, tabId);
		const bboxJson = await evalInContext(
			chromeApi,
			tabId,
			ctxId,
			`JSON.stringify(__lobuFocusBbox(${JSON.stringify(ref_id)}, ${JSON.stringify(document_epoch)}))`,
		);
		const bbox = typeof bboxJson === "string" ? JSON.parse(bboxJson) : bboxJson;
		if (!bbox)
			throw new Error(`click_ref: stale ref (epoch ${document_epoch})`);
		await dispatchMouse(
			chromeApi,
			tabId,
			"mousePressed",
			bbox.x,
			bbox.y,
			button,
			clickCount,
		);
		await dispatchMouse(
			chromeApi,
			tabId,
			"mouseReleased",
			bbox.x,
			bbox.y,
			button,
			clickCount,
		);
		return {
			ok: true,
			observation: { tab_id: tabId, clicked: { x: bbox.x, y: bbox.y } },
		};
	});
}

