function isVisible(el) {
  const style = window.getComputedStyle(el);
  if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') return false;
  return el.offsetWidth > 0 && el.offsetHeight > 0;
}

function inViewport(el) {
  const r = el.getBoundingClientRect();
  return r.top < window.innerHeight && r.bottom > 0 && r.left < window.innerWidth && r.right > 0;
}

function isInteractive(el) {
  const tag = el.tagName.toLowerCase();
  if (['a', 'button', 'input', 'select', 'textarea', 'details', 'summary'].includes(tag)) return true;
  if (el.getAttribute('onclick') != null) return true;
  if (el.getAttribute('tabindex') != null) return true;
  const role = el.getAttribute('role');
  if (role === 'button' || role === 'link') return true;
  if (el.getAttribute('contenteditable') === 'true') return true;
  return false;
}

function isStructural(el) {
  const tag = el.tagName.toLowerCase();
  if (['h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'nav', 'main', 'header', 'footer', 'section', 'article', 'aside'].includes(tag)) return true;
  if (el.getAttribute('role') != null) return true;
  return false;
}

function keepElement(el, filter) {
  const tag = el.tagName.toLowerCase();
  if (['script', 'style', 'meta', 'link', 'title', 'noscript'].includes(tag)) return false;
  if (filter !== 'all' && el.getAttribute('aria-hidden') === 'true') return false;
  if (filter !== 'all' && !isVisible(el)) return false;
  if (filter !== 'all' && !inViewport(el)) return false;
  if (filter === 'interactive') return isInteractive(el);
  if (isInteractive(el)) return true;
  if (isStructural(el)) return true;
  if (computeName(el).length > 0) return true;
  return false;
}

function rectOf(el) {
  const r = el.getBoundingClientRect();
  return {
    x: Math.round(r.left),
    y: Math.round(r.top),
    w: Math.round(r.width),
    h: Math.round(r.height),
  };
}

