function extract(opts) {
  const filter = opts && opts.filter ? opts.filter : 'interactive';
  // Clear refs from a prior extraction, then bump the epoch (stored on
  // <html>). Both live in the DOM so they survive across tool runs.
  for (const el of document.querySelectorAll('[' + REF_ATTR + ']')) {
    el.removeAttribute(REF_ATTR);
  }
  const prevEpoch = parseInt(document.documentElement.getAttribute(EPOCH_ATTR) || '0', 10) || 0;
  const documentEpoch = prevEpoch + 1;
  document.documentElement.setAttribute(EPOCH_ATTR, String(documentEpoch));

